INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Softwarearchitektur > Anpassung bzw. Weiterentwicklung bestehender Software an eine neue Umgebung
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die Anpassung bestehender Software an eine neue Umgebung immer mit einem vollständigen Rewrite verbunden?', 2, '[{"text": "Nein", "correct": true, "because": "Teilweise Anpassungen können ausreichend sein"}, {"text": "Ja", "correct": false, "because": "Nicht immer notwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Weiterentwicklung bestehender Software die ursprüngliche Funktionalität verändern?', 2, '[{"text": "Ja", "correct": true, "because": "Neue Anforderungen können Änderungen erfordern"}, {"text": "Nein", "correct": false, "because": "Veränderungen sind möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Anpassung bestehender Software an eine neue Umgebung die Leistung verbessern?', 2, '[{"text": "Nein", "correct": true, "because": "Ziel ist oft Kompatibilität, nicht zwangsläufig Leistung"}, {"text": "Ja", "correct": false, "because": "Leistung ist nicht immer Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Weiterentwicklung bestehender Software ohne Kenntnis der neuen Umgebung möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Umgebungsanforderungen sind entscheidend"}, {"text": "Ja", "correct": false, "because": "Unwissenheit führt zu Fehlern"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Anpassungen an bestehender Software Sicherheitsrisiken erhöhen?', 2, '[{"text": "Ja", "correct": true, "because": "Neue Schnittstellen oder Fehler können Risiken schaffen"}, {"text": "Nein", "correct": false, "because": "Risiken sind möglich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt ist bei der Anpassung bestehender Software an eine neue Umgebung am wichtigsten?', 2, '[{"text": "Analyse der neuen Umgebung", "correct": true, "because": "Definiert Anforderungen"}, {"text": "Kostenabschätzung", "correct": false, "because": "Sekundär"}, {"text": "Sofortige Programmierung", "correct": false, "because": "Riskant ohne Planung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderung tritt bei der Weiterentwicklung bestehender Software am häufigsten auf?', 3, '[{"text": "Technische Schulden", "correct": true, "because": "Alte Strukturen erschweren Änderungen"}, {"text": "Fehlende Ressourcen", "correct": false, "because": "Häufig, aber nicht primär"}, {"text": "Kundenwiderstand", "correct": false, "because": "Weniger technisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die Anpassung bestehender Software an eine neue Umgebung primär?', 2, '[{"text": "Kompatibilität sicherstellen", "correct": true, "because": "Ermöglicht Funktion in neuer Umgebung"}, {"text": "Kosten senken", "correct": false, "because": "Nicht primäres Ziel"}, {"text": "Benutzerfreundlichkeit erhöhen", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool unterstützt die Weiterentwicklung bestehender Software am besten?', 2, '[{"text": "Refactoring-Tools", "correct": true, "because": "Verbessern Codebasis"}, {"text": "Texteditor", "correct": false, "because": "Zu allgemein"}, {"text": "Marketingsoftware", "correct": false, "because": "Kein Entwicklungsbezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Risiko ist bei der Anpassung bestehender Software an eine neue Umgebung am größten?', 2, '[{"text": "Funktionsverlust", "correct": true, "because": "Änderungen können alte Features brechen"}, {"text": "Geringere Entwicklungsdauer", "correct": false, "because": "Eher Verlängerung"}, {"text": "Kostenreduktion", "correct": false, "because": "Kosten steigen oft"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren müssen bei der Anpassung bestehender Software an eine neue Umgebung berücksichtigt werden?', 4, '[{"text": "Neue Hardwareanforderungen", "correct": true, "because": "Beeinflusst Kompatibilität"}, {"text": "Betriebssystemänderungen", "correct": true, "because": "Erfordert Anpassung"}, {"text": "Sicherheitsstandards", "correct": true, "because": "Neue Umgebung kann strengere Regeln haben"}, {"text": "Farbschema", "correct": false, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden unterstützen die Weiterentwicklung bestehender Software?', 3, '[{"text": "Refactoring", "correct": true, "because": "Verbessert Struktur"}, {"text": "Modultests", "correct": true, "because": "Sichert Funktion"}, {"text": "Dokumentation", "correct": true, "because": "Erleichtert Verständnis"}, {"text": "Werbekampagnen", "correct": false, "because": "Kein Entwicklungsbezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen treten bei der Anpassung bestehender Software auf?', 4, '[{"text": "Legacy-Code", "correct": true, "because": "Schwer wartbar"}, {"text": "Inkompatible Schnittstellen", "correct": true, "because": "Erschweren Integration"}, {"text": "Fehlende Dokumentation", "correct": true, "because": "Verzögert Verständnis"}, {"text": "Geringere Komplexität", "correct": false, "because": "Komplexität steigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Weiterentwicklung bestehender Software?', 3, '[{"text": "Kosteneinsparung", "correct": true, "because": "Vermeidet Neuentwicklung"}, {"text": "Bewährte Funktionalität", "correct": true, "because": "Nutzt bestehende Basis"}, {"text": "Schnellere Umsetzung", "correct": true, "because": "Baut auf Vorhandenem auf"}, {"text": "Höhere Lizenzkosten", "correct": false, "because": "Kein Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei der Anpassung bestehender Software essenziell?', 3, '[{"text": "Anforderungsanalyse", "correct": true, "because": "Definiert Ziele"}, {"text": "Kompatibilitätstests", "correct": true, "because": "Sichert Funktion"}, {"text": "Code-Review", "correct": true, "because": "Findet Schwachstellen"}, {"text": "Marketingplanung", "correct": false, "because": "Kein Entwicklungsstep"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Anpassung bestehender Software erfordert Kenntnis der neuen Umgebung. b) Sie führt immer zu einem vollständigen Rewrite.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kenntnis ja, Rewrite nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Weiterentwicklung kann Sicherheitsrisiken erhöhen. b) Sie ist unabhängig von der ursprünglichen Software.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Risiken ja, Abhängigkeit nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Anpassung bestehender Software spart oft Kosten. b) Neue Technologien sind immer erforderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kostenersparnis ja, Technologien nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Refactoring unterstützt die Weiterentwicklung bestehender Software. b) Leistungsverbesserung ist das einzige Ziel der Anpassung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Refactoring ja, Leistung nicht allein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Kompatibilitätstests sind bei der Anpassung essenziell. b) Legacy-Code ist kein Hindernis für die Weiterentwicklung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tests ja, Legacy-Code oft hinderlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

